import assert from 'node:assert/strict'
import { DatabaseSync } from 'node:sqlite'
import { pathToFileURL } from 'node:url'
import { Context } from '@deepseek-ai/cordis'
import Storage from '@deepseek-ai/dsh-storage'
import { DomainFacility, type KvTable } from '@deepseek-ai/dsh-storage-domain'
import { SessionId } from '@deepseek-ai/dsh-session'
import { WorkspaceId } from '@deepseek-ai/dsh-workspace'
import { AgentTeamLedger, agentTeamHumanActor } from '../packages/agent-team/src/ledger.ts'
import { agentTeamDomainSpec } from '../packages/agent-team/src/spec.ts'
import { MemoryMediaPool, MemoryStorageBackend } from '../packages/agent-team/tests/helpers/memory-backend.ts'
import type { AgentTeamMemberId, AgentTeamOperation, AgentTeamOperationId, AgentTeamRequestId } from '../packages/agent-team/src/types.ts'
import { calculateTrialMetrics } from './team-trial-metrics.ts'

const workspaceId = WorkspaceId('workspace:metrics')
const human = agentTeamHumanActor()
const actor = (memberId: AgentTeamMemberId) => ({ kind: 'member' as const, memberId, handle: 'worker' })
const operationId = (sequence: number) => `operation:${sequence}` as AgentTeamOperationId
const table = (records: AgentTeamOperation[]) => new Map(records.map(operation => [operation.operationId, operation]))

function reminder(sequence: number, previousOperationId: AgentTeamOperationId | null, memberId: AgentTeamMemberId): AgentTeamOperation {
  return { sequence, operationId: operationId(sequence), previousOperationId, requestId: `metrics:${sequence}` as AgentTeamRequestId,
    occurredAt: '2026-10-26T00:00:00.000Z', actor: { kind: 'host', handle: 'host' }, kind: 'team/reminder-raised',
    data: { taskRef: 'task:1' as never, kind: 'stalled', recipient: memberId, baselineSequence: 1,
      inbox: { attention: { set: [], removed: [] }, directMarkers: { added: [], removed: [] }, activityMarkers: { added: [], removed: [] },
        reminderMarkers: { added: [{ memberId, threadRef: 'thread:1', taskRef: 'task:1', kind: 'stalled', sequence, baselineSequence: 1 }], removed: [] } } } } as AgentTeamOperation
}

async function main() {
  assert.throws(() => calculateTrialMetrics([reminder(1, null, 'member:worker' as AgentTeamMemberId)]), /initialization/)
  assert.equal(calculateTrialMetrics([]).range.utcCalendarDays, 0)

  const pool = new MemoryMediaPool()
  const ctx = new Context()
  await ctx.plugin(Storage)
  ctx.storage.backend.register('memory', new MemoryStorageBackend(pool))
  const facility = new DomainFacility(ctx, { backend: 'memory', routes: {} })
  ctx.storage.mount('domain', facility)
  ctx.provide('storageDomain', facility)
  const operations = await (await ctx.storageDomain.open(agentTeamDomainSpec)).table('operations') as unknown as KvTable<AgentTeamOperationId, AgentTeamOperation>
  let instant = Date.parse('2026-10-24T23:59:00.000Z')
  const ledger = new AgentTeamLedger(operations, { rulesVersion: 2, occurredAt: () => new Date(instant++).toISOString() })
  await ledger.initialize()
  const projectRef = (await ledger.createProject({ requestId: 'metrics:project' as AgentTeamRequestId, actor: human, workspaceId, name: 'metrics', description: '', memberIds: [] })).value.project.projectRef
  const memberId = 'member:worker' as AgentTeamMemberId
  await ledger.addMember({ requestId: 'metrics:member' as AgentTeamRequestId, actor: human, workspaceId, handle: 'worker', description: '', presetId: 'team-member',
    member: { memberId, sessionId: SessionId('session:worker'), workspaceId, handle: 'worker', description: '', presetId: 'team-member', privateMemoryPath: '/tmp/worker', state: 'enabled' }, projectRefs: [projectRef] })
  await ledger.addProjectOwner({ requestId: 'metrics:owner' as AgentTeamRequestId, actor: human, workspaceId, projectRef, memberId })
  const started = await ledger.startThread({ requestId: 'metrics:thread' as AgentTeamRequestId, actor: actor(memberId), workspaceId, projectRef, kind: 'discussion', body: 'Start' })
  const threadRef = started.value.thread!.threadRef
  await ledger.readThread({ requestId: 'metrics:read' as AgentTeamRequestId, actor: human, workspaceId, threadRef })
  instant = Date.parse('2026-10-25T00:01:00.000Z')
  await ledger.postMainMessage({ requestId: 'metrics:main' as AgentTeamRequestId, actor: human, workspaceId, projectRef, body: '@worker hello' })
  const records = [...pool.media.get('agent_team')!.tables.get('operations')!.values()] as AgentTeamOperation[]
  const result = calculateTrialMetrics([...operations])
  assert.equal(result.range.utcCalendarDays, 3)
  assert.equal(result.delivery.allMembers.immediateNotificationFactsByMember[memberId], 1)
  assert.deepEqual(result.delivery.owners.byUtcDay, [{ date: '2026-10-25', memberId, immediateNotificationFacts: 1 }])

  const stored = [...table(records)]
  const databasePath = process.argv[2]
  if (databasePath !== undefined) {
    const database = new DatabaseSync(databasePath)
    database.exec('CREATE TABLE u_agent_team_operations (key TEXT PRIMARY KEY, value TEXT NOT NULL)')
    const insert = database.prepare('INSERT INTO u_agent_team_operations VALUES (?, ?)')
    for (const operation of stored) insert.run(operation.operationId, JSON.stringify(operation))
    database.close()
  }
  await facility.closeAll()
