1	// Usage: node --import tsx scripts/team-trial-metrics.mjs [ledger-copy.sqlite] [--json]
2	// Reads a SQLite copy directly. Validation replays in memory; the source is never opened for writing.
3	import { DatabaseSync } from 'node:sqlite'
4	import { pathToFileURL } from 'node:url'
5	import { AgentTeamLedger } from '../packages/agent-team/src/ledger.ts'
6	import { agentTeamOperationSchema } from '../packages/agent-team/src/spec.ts'
7	import { reviewReminderRecipient } from '../packages/agent-team/src/task-reminders.ts'
8	
9	const HUMAN = 'member:human'
10	const DAY_MS = 86400000
11	const releaseKinds = new Set(['team/member-workspace-left', 'team/member-archived', 'team/member-removed', 'team/project-archived', 'team/project-owner-removed'])
12	const keyOf = marker => [marker.memberId, marker.taskRef, marker.kind, marker.baselineSequence].join('|')
13	const percent = (part, total) => total === 0 ? null : Math.round(part / total * 1000) / 10
14	const increment = (map, key, amount = 1) => map.set(key, (map.get(key) ?? 0) + amount)
15	
16	function readOperations(path) {
17	  const database = new DatabaseSync(path, { readOnly: true })
18	  try {
19	    return database.prepare('SELECT key, value FROM u_agent_team_operations').all()
20	      .map(row => [row.key, agentTeamOperationSchema.parse(JSON.parse(row.value))])
21	      .sort((left, right) => left[1].sequence - right[1].sequence)
22	  } finally { database.close() }
23	}
24	
25	function newState() {
26	  return { projects: new Map(), members: new Map(), owners: new Map(), tasks: new Map(), claims: new Map(),
27	    follows: new Map(), statusBaselines: new Map(), latestFacts: new Map(), reminders: new Map(), reminderEpisodes: new Map() }
28	}
29	
30	function apply(state, operation) {
31	  const data = operation.data
32	  if (operation.kind === 'team/project-created') {
33	    state.projects.set(data.project.projectRef, data.project)
34	    state.owners.set(data.project.projectRef, new Set())
35	  }
